<?php require __DIR__.'/../layouts/header.php'; ?><h1>Painel administrativo</h1><div class="stats"><div class="panel"><small>Pedidos registrados</small><h2><?=$stats['pedidos']?></h2></div><div class="panel"><small>Vendas concluídas</small><h2>R$ <?=number_format($stats['vendas'],2,',','.')?></h2></div></div>
<div class="panel"><h2><?= $editProduct ? 'Editar produto' : 'Cadastrar produto' ?></h2><form class="admin-form" method="post" action="index.php?action=admin_product"><?=csrfField()?><input type="hidden" name="id" value="<?=e($editProduct['id']??'')?>"><label>Nome<input required name="nome" value="<?=e($editProduct['nome']??'')?>"></label><label>Categoria<select name="categoria_id"><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=((int)($editProduct['categoria_id']??0)===(int)$c['id'])?'selected':''?>><?=e($c['nome'])?></option><?php endforeach;?></select></label><label>Preço<input required type="number" min="0.01" step="0.01" name="preco" value="<?=e($editProduct['preco']??'')?>"></label><label>Imagem (URL opcional)<input name="imagem" value="<?=e($editProduct['imagem']??'')?>"></label><label class="wide">Descrição<textarea name="descricao"><?=e($editProduct['descricao']??'')?></textarea></label><label><input type="checkbox" name="ativo" <?=(!isset($editProduct['ativo']) || $editProduct['ativo'])?'checked':''?>> Produto ativo</label><button class="btn">Salvar produto</button><?php if($editProduct):?><a href="index.php?action=admin">Cancelar edição</a><?php endif;?></form></div>
<div class="panel"><h2>Produtos cadastrados</h2><table><tr><th>Produto</th><th>Preço</th><th>Status</th><th>Ação</th></tr><?php foreach($products as $p):?><tr><td><?=e($p['nome'])?></td><td>R$ <?=number_format($p['preco'],2,',','.')?></td><td><?=$p['ativo']?'Ativo':'Inativo'?></td><td><a href="index.php?action=admin_edit&id=<?=$p['id']?>">Editar</a> · <form method="post" action="index.php?action=admin_delete" class="inline" data-confirm="Desativar este produto?"><?=csrfField()?> <input type="hidden" name="id" value="<?=$p['id']?>"><button class="link-button danger" type="submit">Desativar</button></form></td></tr><?php endforeach;?></table></div>
<div class="panel"><h2>Pedidos recebidos</h2><?php if(!$orders):?><p>Nenhum pedido ainda.</p><?php else:?><table><tr><th>Pedido</th><th>Cliente</th><th>Data</th><th>Total</th><th>Status</th><th>Atualizar</th></tr><?php foreach($orders as $o):?><tr><td>#<?=$o['id']?></td><td><?=e($o['cliente'])?></td><td><?=date('d/m/Y H:i',strtotime($o['criado_em']))?></td><td>R$ <?=number_format($o['total'],2,',','.')?></td><td><?=e($o['status'])?></td><td><form method="post" action="index.php?action=admin_status" class="inline"><?=csrfField()?><input type="hidden" name="id" value="<?=$o['id']?>"><select name="status"><?php foreach(['Pendente','Preparando','Pronto','Concluído','Cancelado'] as $st):?><option <?=$o['status']===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select><button class="btn small">Salvar</button></form></td></tr><?php endforeach;?></table><?php endif;?></div><?php require __DIR__.'/../layouts/footer.php'; ?>
